lib='''def draw_strokes(grid, glyphs):
    """Each colored cell draws its fixed stroke glyph (own color, filler 5); overlapping strokes give 4."""
    h, w = len(grid), len(grid[0])
    cells = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            for dr, dc, val in glyphs.get(v, []):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    cells.setdefault((rr, cc), []).append(val)
    out = [[0] * w for _ in range(h)]
    crossings = []
    for (r, c), vals in cells.items():
        if len(vals) > 1:
            out[r][c] = 4
            crossings.append((r, c))
        else:
            out[r][c] = vals[0]
    return out, crossings

def crossing_diagonals(painted):
    """From each stroke crossing (marked 4), a diagonal of 4s runs down-left to the grid edge."""
    grid, crossings = painted
    h, w = len(grid), len(grid[0])
    for r, c in crossings:
        rr, cc = r + 1, c - 1
        while rr < h and cc >= 0:
            grid[rr][cc] = 4
            rr += 1; cc -= 1
    return grid

def stroke_glyphs():
    """Fixed stroke glyph per color: offsets (dr, dc, value) relative to the anchor cell."""
